const state={me:null,settings:{},auctions:[],serverOffset:0,deferredInstall:null,adminTab:'overview',editingAuction:null,quickPhotos:[],quickPhotoKey:null,quickOriginalImageIds:[],quickSavedAuction:null};
const $=(s,root=document)=>root.querySelector(s); const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const randMoney=c=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(Number(c||0)/100);
const fmtDate=d=>new Intl.DateTimeFormat('en-ZA',{dateStyle:'medium',timeStyle:'short'}).format(new Date(d));
const now=()=>Date.now()+state.serverOffset;
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast show'+(error?' error':'');clearTimeout(toast._t);toast._t=setTimeout(()=>t.className='toast',3600)}
async function api(path,opt={}){const o={credentials:'include',...opt};if(o.body&&!(o.body instanceof FormData)&&typeof o.body!=='string'){o.headers={...(o.headers||{}),'content-type':'application/json'};o.body=JSON.stringify(o.body)}const r=await fetch('/api/'+path.replace(/^\//,''),o);const ct=r.headers.get('content-type')||'';const data=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw Object.assign(new Error(data?.error||data||`Request failed (${r.status})`),{status:r.status,data});return data}
function setServerTime(s){if(s)state.serverOffset=new Date(s).getTime()-Date.now()}
async function bootstrap(){try{const d=await api('bootstrap');state.me=d.me;state.settings=d.settings;setServerTime(d.serverTime)}catch(e){console.error(e)}render()}
function route(){return location.pathname.replace(/^\/|\/$/g,'')||'home'}
function go(path){history.pushState({},'',path.startsWith('/')?path:'/'+path);render();scrollTo({top:0,behavior:'smooth'})}
window.addEventListener('popstate',render);
document.addEventListener('click',e=>{const a=e.target.closest('[data-link]');if(a){e.preventDefault();go(a.getAttribute('href')||a.dataset.link)}});
function countdown(end,status){if(['closed','unsold','cancelled'].includes(status))return status==='closed'?'Ended · sold':status==='unsold'?'Ended · unsold':'Cancelled';const diff=new Date(end).getTime()-now();if(diff<=0)return 'Closing…';const s=Math.floor(diff/1000),d=Math.floor(s/86400),h=Math.floor((s%86400)/3600),m=Math.floor((s%3600)/60),sec=s%60;if(d)return `${d}d ${h}h`;if(h)return `${h}h ${m}m`;return `${m}m ${String(sec).padStart(2,'0')}s`}
function statusChip(a){const status=(a.status||'').toLowerCase();const text=status==='live'?'Live now':status==='scheduled'?'Upcoming':status==='closed'?'Sold':status==='unsold'?'Unsold':status;return `<span class="chip ${status}">${esc(text)}</span>`}
function card(a){const img=a.images?.[0]?.url;const bid=a.currentBidCents==null?a.openingBidCents:a.currentBidCents;const label=a.currentBidCents==null?'Opening bid':'Current bid';return `<article class="card auction-card" data-link="/auction/${esc(a.id)}">
  <div class="card-img">${img?`<img loading="lazy" src="${esc(img)}" alt="${esc(a.images[0].alt||a.title)}">`:''}${statusChip(a)}</div>
  <div class="card-body"><div class="label">${esc(a.category)}</div><h3 class="card-title">${esc(a.title)}</h3>
    <div class="card-meta"><div><div class="label">${label}</div><div class="price">${randMoney(bid)}</div></div><div class="right"><div class="label">${a.status==='scheduled'?'Starts':'Time left'}</div><div class="countdown" data-countdown="${esc(a.currentEndAt)}" data-status="${esc(a.status)}">${a.status==='scheduled'?fmtDate(a.startAt):countdown(a.currentEndAt,a.status)}</div></div></div>
  </div></article>`}
function header(){return `<header class="topbar"><div class="container nav"><a class="brand" href="/" data-link><span class="brandmark">W</span><span>Whacky Auctions</span></a>
<nav class="navlinks"><a href="/" data-link>Auctions</a>${state.me?`<a href="/my-bids" data-link>My bids</a><a href="/watchlist" data-link>Watchlist</a><a href="/wins" data-link>Wins</a>`:''}<a href="https://pay.yoco.com/whacky-auctions" target="_blank" rel="noopener">Pay with Yoco</a><a href="/legal" data-link>Legal</a>${state.me?.role==='admin'?'<a href="/admin" data-link>Admin</a>':''}${state.me?`<button id="accountBtn">${esc(state.me.firstName)}</button>`:'<button id="loginBtn">Sign in</button>'}</nav>
<button class="btn btn-secondary mobile-menu" id="mobileBtn">Menu</button></div></header>`}
function footer(){return `<footer class="footer"><div class="container footer-grid"><div><div class="brand"><span class="brandmark">W</span><span>Whacky Auctions</span></div><p class="muted small">Unique finds. Low opening bids. Fair rolling soft close.</p><p class="small">Whacky Auctions PTY LTD · South Africa</p></div><div><b>Explore</b><a href="/" data-link>All auctions</a><a href="/my-bids" data-link>My bids</a><a href="/watchlist" data-link>Watchlist</a></div><div><b>Legal</b><a href="/legal" data-link>Legal centre</a><a href="/install" data-link>Install app</a><a href="/legal/privacy-policy.pdf" target="_blank">Privacy Policy</a><a href="/legal/terms-auction-rules.pdf" target="_blank">Terms & Auction Rules</a><a href="https://pay.yoco.com/whacky-auctions" target="_blank" rel="noopener">Pay securely with Yoco ↗</a></div></div></footer>`}
function launchNotice(){if(state.settings.tradingEnabled)return'';return `<div class="container launch-lock"><div class="notice"><b>Pre-launch mode:</b> browsing, account setup and administration are ready, but binding bids are locked until Whacky Auctions activates trading after its required registrations and payment gateway are in place.</div></div>`}
async function loadAuctions(){const d=await api('auctions');state.auctions=d.auctions;setServerTime(d.serverTime);return d.auctions}
async function home(){let auctions=[];try{auctions=await loadAuctions()}catch(e){toast(e.message,true)}const live=auctions.filter(a=>a.status==='live'),up=auctions.filter(a=>a.status==='scheduled'),ended=auctions.filter(a=>['closed','unsold'].includes(a.status));return `${header()}${launchNotice()}<main>
<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">⚡ Rolling 2-minute soft close</span><h1>Find something <span class="grad">Whacky.</span><br>Bid from low.</h1><p>South African online auctions built for transparent condition disclosure, genuinely low opening bids and fair anti-sniping finishes.</p><div class="hero-actions"><a class="btn btn-primary" href="#auctions">Browse auctions</a>${state.me?'':`<button class="btn btn-secondary" id="heroRegister">Create bidder account</button>`}</div></div><aside class="launch-card"><div class="label">Our auction rule</div><div class="big">2:00</div><div class="mini">A valid bid in the final two minutes resets that lot to a full two-minute window. It can extend repeatedly until bidding stops.</div><div class="softclose"><b>No last-second sniping.</b><div class="mini">Every genuine bidder gets a fair chance to respond.</div></div></aside></div></section>
<section id="auctions" class="section"><div class="container"><div class="section-head"><div><div class="label">Marketplace</div><h2>${live.length?'Live auctions':up.length?'Upcoming auctions':'Auctions'}</h2></div><div class="muted">${auctions.length} lot${auctions.length===1?'':'s'}</div></div>${auctions.length?`<div class="grid">${[...live,...up,...ended].map(card).join('')}</div>`:`<div class="empty"><h3>Stock is being prepared.</h3><p>Auctions created in the admin dashboard will appear here when published.</p></div>`}</div></section></main>${footer()}`}
async function auctionPage(id){let d;try{d=await api('auctions/'+id);setServerTime(d.serverTime)}catch(e){return `${header()}<main class="section"><div class="container"><div class="notice bad">${esc(e.message)}</div></div></main>${footer()}`};const a=d.auction;const imgs=a.images||[];const main=imgs[0]?.url;const high=a.currentBidCents??a.openingBidCents;const min=a.currentBidCents==null?a.openingBidCents:a.currentBidCents+a.bidIncrementCents;const canBid=state.me&&state.me.verified&&!state.me.suspended&&state.settings.tradingEnabled&&['live','scheduled'].includes(a.status)&&now()>=new Date(a.startAt).getTime()&&now()<new Date(a.currentEndAt).getTime();const myHigh=state.me&&a.highBidderId===state.me.id;return `${header()}${launchNotice()}<main class="detail"><div class="container detail-grid"><section class="gallery"><div class="main-photo">${main?`<img id="mainPhoto" src="${esc(main)}" alt="${esc(a.title)}">`:`<div class="empty">No image yet</div>`}</div>${imgs.length>1?`<div class="thumbs">${imgs.map((im,i)=>`<button class="thumb ${i===0?'active':''}" data-photo="${esc(im.url)}"><img src="${esc(im.url)}" alt="${esc(im.alt||a.title)}"></button>`).join('')}</div>`:''}</section><section><div class="label">${esc(a.category)}</div><h1>${esc(a.title)}</h1><div class="toolbar">${statusChip(a)}<button class="btn btn-secondary" id="watchBtn">${a.watched?'★ Watching':'☆ Watch'}</button></div>
<div class="bidbox"><div class="label">${a.currentBidCents==null?'Opening bid':'Current bid'}</div><div class="price" style="font-size:42px">${randMoney(high)}</div><div class="muted small">${a.bidCount} bid${a.bidCount===1?'':'s'} · increment ${randMoney(a.bidIncrementCents)}</div><div class="kv"><div><div class="label">${a.status==='scheduled'?'Starts':'Time left'}</div><b class="countdown" data-countdown="${esc(a.currentEndAt)}" data-status="${esc(a.status)}">${a.status==='scheduled'?fmtDate(a.startAt):countdown(a.currentEndAt,a.status)}</b></div><div><div class="label">Reserve</div><b>${a.reserveDisclosed?(a.reserveMet?'Met / not required':'Not yet met'):'Not disclosed'}</b></div></div>
<div class="soft-badge"><span>⏱️</span><div><b>Soft close active</b><div class="muted small">Any valid bid in the final ${Math.round(a.softCloseSeconds/60)} minute${a.softCloseSeconds===60?'':'s'} restores a full ${Math.round(a.softCloseSeconds/60)}-minute window. Extensions can repeat.</div></div></div>
${myHigh?'<div class="notice good" style="margin-top:12px">You currently hold the highest bid.</div>':''}
${a.order?`<div class="notice good" style="margin-top:12px"><b>Winning order</b><br>Total payable: <b>${randMoney(a.order.totalCents)}</b> · ${esc(a.order.status)}${a.order.status!=='paid'?`<div style="margin-top:10px"><button class="btn btn-primary" id="payNow" ${state.settings.paymentGatewayEnabled?'':'disabled'}>${state.settings.paymentGatewayEnabled?'Pay now':'Payment gateway coming at launch'}</button></div>`:''}</div>`:''}
${canBid?`<div class="bidrow"><input class="input" id="bidAmount" type="number" inputmode="decimal" min="${min/100}" step="${a.bidIncrementCents/100}" value="${(min/100).toFixed(2)}"><button class="btn btn-accent" id="placeBid">Place bid</button></div><div class="small muted" style="margin-top:8px">By placing a bid you accept the auction rules. A bid may be retracted before the sale is completed, subject to the rules.</div>`:bidGate(a)}
</div><div class="tabs"><button class="tab active" data-tab="details">Details</button><button class="tab" data-tab="bids">Bid history</button><button class="tab" data-tab="rules">Rules</button></div><div id="tabBody">${detailTab(a,'details')}</div></section></div></main>${footer()}`}
function bidGate(a){if(!state.me)return'<div class="notice" style="margin-top:12px">Sign in and complete bidder registration to bid.</div>';if(!state.me.verified)return'<div class="notice" style="margin-top:12px">Your bidder account is awaiting verification.</div>';if(!state.settings.tradingEnabled)return'<div class="notice" style="margin-top:12px">Binding bids are locked during pre-launch mode.</div>';if(a.status==='scheduled')return`<div class="notice" style="margin-top:12px">Bidding opens ${fmtDate(a.startAt)}.</div>`;return'<div class="notice" style="margin-top:12px">This auction is not open for bidding.</div>'}
function detailTab(a,tab){if(tab==='bids')return a.bids?.length?`<div class="table-wrap"><table><thead><tr><th>Bidder</th><th>Amount</th><th>Time</th><th>Status</th></tr></thead><tbody>${a.bids.map(b=>`<tr><td>${esc(b.bidder)}${b.isMine?' <span class="chip">You</span>':''}</td><td>${randMoney(b.amountCents)}</td><td>${fmtDate(b.createdAt)}</td><td>${b.retractedAt?'Retracted':b.isMine&&['scheduled','live'].includes(a.status)?`<button class="btn btn-secondary small" data-retract-bid="${b.id}">Retract bid</button>`:'Valid'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No bids yet.</div>';if(tab==='rules')return `<div class="panel"><h3>Auction rules</h3><p>Opening bid: <b>${randMoney(a.openingBidCents)}</b> · minimum increment: <b>${randMoney(a.bidIncrementCents)}</b>.</p><p>Soft close: a valid bid in the final ${a.softCloseSeconds} seconds extends the lot so that a full ${a.softCloseSeconds} seconds remain. Extensions may repeat without a fixed maximum.</p><p>Buyer premium: <b>${a.buyerPremiumPercent}%</b>. ${esc(a.vatNote)}</p><p>Payment deadline: <b>${a.paymentDeadlineHours} hours</b> after the sale, subject to the auction-specific rules.</p><p>${esc(a.inspectionNote)}</p><p>${esc(a.collectionNote)}</p><p>${esc(a.storageFeeNote)}</p><p><a href="/legal/terms-auction-rules.pdf" target="_blank">Read the complete App Terms & Master Rules of Auction ↗</a></p><p><a href="/rules/${esc(a.id)}" data-link>Open the auction-specific rules / printable schedule →</a></p></div>`;return `<div class="panel"><h3>Condition & description</h3><p><b>Condition:</b> ${esc(a.condition)}</p><p>${esc(a.description).replace(/\n/g,'<br>')}</p><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><div class="form-grid"><div><div class="label">Auctioneer</div><b>${esc(a.auctioneerName||'To be confirmed before publication')}</b></div><div><div class="label">Closing</div><b>${fmtDate(a.currentEndAt)}</b></div></div></div>`}
async function accountList(which){if(!state.me)return needLogin();let d;try{d=await api('me/'+which)}catch(e){return errorPage(e.message)}const titles={bids:'My bids',watchlist:'Watchlist',wins:'Wins'};return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Account</div><h2>${titles[which]}</h2></div></div>${d.auctions.length?`<div class="grid">${d.auctions.map(card).join('')}</div>`:`<div class="empty">Nothing here yet.</div>`}</div></main>${footer()}`}
function needLogin(){return `${header()}<main class="section"><div class="container"><div class="empty"><h2>Sign in required</h2><button class="btn btn-primary" id="loginHere">Sign in</button></div></div></main>${footer()}`}
function errorPage(msg){return `${header()}<main class="section"><div class="container"><div class="notice bad">${esc(msg)}</div></div></main>${footer()}`}
async function profile(){if(!state.me)return needLogin();let notes=[];try{notes=(await api('me/notifications')).notifications}catch{}return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Account</div><h2>${esc(state.me.firstName)} ${esc(state.me.lastName)}</h2></div><button class="btn btn-secondary" id="logoutBtn">Sign out</button></div><div class="detail-grid"><div class="panel"><h3>Bidder status</h3><div class="notice ${state.me.verified?'good':''}">${state.me.verified?'<span class="badge-dot"></span>Verified to bid':'Verification pending — the admin must verify your bidder registration before binding bids can be placed.'}</div><p><b>Email:</b> ${esc(state.me.email)}</p><p><b>Mobile:</b> ${esc(state.me.mobile||'')}</p><h3>Change password</h3><form id="passwordForm" class="admin-form"><input class="input" type="password" name="currentPassword" placeholder="Current password" required><input class="input" type="password" name="newPassword" minlength="10" placeholder="New password (10+ characters)" required><button class="btn btn-secondary">Change password</button></form></div><div class="panel"><div class="section-head"><h3>Notifications</h3><button class="btn btn-secondary" id="readNotes">Mark read</button></div>${notes.length?notes.map(n=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><b>${esc(n.message)}</b><div class="muted small">${fmtDate(n.created_at)}</div></div>`).join(''):'<div class="muted">No notifications.</div>'}</div></div></div></main>${footer()}`}
function legal(){return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Compliance</div><h2>Legal centre</h2></div></div><div class="panel legal-list"><a class="legal-link" target="_blank" href="/legal/privacy-policy.pdf"><div><b>POPIA Privacy Notice & Privacy Policy</b><div class="muted small">Version 1.0 · Effective 12 September 2026</div></div><span>Open PDF ↗</span></a><a class="legal-link" target="_blank" href="/legal/terms-auction-rules.pdf"><div><b>App Terms & Master Rules of Auction</b><div class="muted small">Includes the rolling soft-close rule</div></div><span>Open PDF ↗</span></a><a class="legal-link" target="_blank" href="/legal/live-auction-rules-template.pdf"><div><b>Live Auction Rules Template</b><div class="muted small">Auction-specific schedule and statutory records template</div></div><span>Open PDF ↗</span></a><div class="legal-link"><div><b>PAIA Manual</b><div class="muted small">Available from the Information Officer at rugs.san88@gmail.com. A final web copy will be added when the submitted manual file is supplied to the app repository.</div></div><span>PAIA</span></div></div></div></main>${footer()}`}
function installPage(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent);return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Mobile app</div><h2>Install Whacky Auctions</h2></div></div><div class="detail-grid"><div class="panel"><h3>Android</h3><p>Once the site is live, Chrome can install Whacky Auctions as a full-screen app directly from the browser.</p><button class="btn btn-primary" id="installPageBtn" ${state.deferredInstall?'':'disabled'}>${state.deferredInstall?'Install on this device':'Open in Chrome and choose Install app'}</button><p class="muted small">An Android wrapper project is prepared for APK packaging; the hosted PWA can be installed directly from Chrome as soon as the site is live.</p></div><div class="panel"><h3>iPhone / iPad</h3><p>Open Whacky Auctions in Safari, tap <b>Share</b>, choose <b>Add to Home Screen</b>, then confirm <b>Add</b>. It opens in standalone app mode.</p><p class="muted small">${ios?'You appear to be using an Apple mobile device.':'Apple does not allow a generally downloadable signed iPhone IPA without Apple Developer signing/provisioning; the installable web app works without App Store approval.'}</p></div></div></div></main>${footer()}`}
async function rulesPage(id){let d;try{d=await api('auctions/'+id)}catch(e){return errorPage(e.message)}const a=d.auction;return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Auction-specific rules</div><h2>${esc(a.title)}</h2></div><button class="btn btn-secondary" id="printRules">Print / Save PDF</button></div><div class="panel rules-sheet"><p><b>Auction platform:</b> Whacky Auctions PTY LTD</p><p><b>Appointed auctioneer:</b> ${esc(a.auctioneerName||'To be completed before publication')}</p><p><b>Start:</b> ${fmtDate(a.startAt)}<br><b>Scheduled close:</b> ${fmtDate(a.scheduledEndAt)}<br><b>Current close:</b> ${fmtDate(a.currentEndAt)}</p><p><b>Opening bid:</b> ${randMoney(a.openingBidCents)}<br><b>Minimum increment:</b> ${randMoney(a.bidIncrementCents)}<br><b>Buyer premium:</b> ${a.buyerPremiumPercent}%</p><h3>Rolling soft close</h3><p>A valid bid received during the final ${a.softCloseSeconds} seconds resets the close so that a full ${a.softCloseSeconds} seconds remain. Every further valid bid inside the renewed final window repeats the extension. There is no fixed maximum number of extensions.</p><h3>Condition and inspection</h3><p><b>Condition:</b> ${esc(a.condition)}</p><p>${esc(a.inspectionNote)}</p><h3>Payment and collection</h3><p>Payment deadline: ${a.paymentDeadlineHours} hours after completion. ${esc(a.vatNote)}</p><p>${esc(a.collectionNote)}</p><p>${esc(a.storageFeeNote)}</p><h3>Master terms</h3><p>These auction-specific rules must be read with the <a href="/legal/terms-auction-rules.pdf" target="_blank">Whacky Auctions App Terms & Master Rules of Auction</a>. Where a mandatory legal rule applies, it prevails over any inconsistent contractual term.</p></div></div></main>${footer()}`}
function adminSetup(){return `${header()}<main class="section"><div class="container"><div class="panel" style="max-width:620px;margin:auto"><div class="label">One-time configuration</div><h2>Set up Whacky Auctions admin</h2><p class="muted">Use the setup code provided with this deployment. This page stops working after the first administrator is created.</p><form id="adminSetupForm" class="admin-form"><div class="field"><label>Setup code</label><input class="input code" name="code" required autocomplete="off"></div><div class="field"><label>Choose admin password</label><input class="input" type="password" minlength="10" name="password" required></div><button class="btn btn-primary">Create administrator</button></form></div></div></main>${footer()}`}
async function admin(){if(!state.me||state.me.role!=='admin')return errorPage('Administrator access required.');let dash;try{dash=await api('admin/dashboard')}catch(e){return errorPage(e.message)}const side=`<aside class="side"><button data-admin-tab="overview" class="${state.adminTab==='overview'?'active':''}">Overview</button><button data-admin-tab="auctions" class="${state.adminTab==='auctions'?'active':''}">Quick List</button><button data-admin-tab="users" class="${state.adminTab==='users'?'active':''}">Bidders</button><button data-admin-tab="records" class="${state.adminTab==='records'?'active':''}">Records</button></aside>`;let body='';if(state.adminTab==='overview')body=adminOverview(dash);if(state.adminTab==='auctions')body=await adminAuctions();if(state.adminTab==='users')body=await adminUsers();if(state.adminTab==='records')body=adminRecords();return `${header()}<main class="section"><div class="container"><div class="section-head"><div><div class="label">Operations</div><h2>Admin dashboard</h2></div></div><div class="admin-layout">${side}<section>${body}</section></div></div></main>${footer()}`}
function adminOverview(d){const reg=!!d.settings.dealer_registration_confirmed;const pay=!!d.settings.payment_gateway_enabled;const ready=reg&&pay;return `<div class="admin-grid"><div class="stat"><span class="label">Users</span><b>${d.stats.users}</b></div><div class="stat"><span class="label">Auctions</span><b>${d.stats.auctions}</b></div><div class="stat"><span class="label">Bids</span><b>${d.stats.bids}</b></div><div class="stat"><span class="label">To verify</span><b>${d.stats.pendingVerification}</b></div></div><div class="panel" style="margin-top:16px"><h3>Launch status</h3><div class="notice ${d.settings.trading_enabled?'good':''}"><b>${d.settings.trading_enabled?'Trading enabled':'Launch lock active'}</b><br>${d.settings.trading_enabled?'Binding auctions can run.':'Binding bids and publication remain locked until both launch requirements are complete.'}</div><div class="kv"><div><div class="label">SAPS second-hand-goods registration</div><b>${reg?'Recorded':'Pending'}</b>${reg&&d.settings.dealer_registration_number?`<div class="muted small">${esc(d.settings.dealer_registration_number)}${d.settings.dealer_registration_expiry?` · expires ${esc(d.settings.dealer_registration_expiry)}`:''}</div>`:''}</div><div><div class="label">Payment gateway</div><b>${pay?'Connected':'Pending'}</b></div></div><form id="dealerRegistrationForm" class="admin-form" style="margin-top:16px"><div class="form-grid"><div class="field"><label>SAPS registration number</label><input class="input" name="registrationNumber" value="${esc(d.settings.dealer_registration_number||'')}" placeholder="Enter after SAPS approval"></div><div class="field"><label>Expiry date (if shown)</label><input class="input" type="date" name="expiryDate" value="${esc(d.settings.dealer_registration_expiry||'')}"></div></div><label class="switch"><input type="checkbox" name="confirmed" ${reg?'checked':''}> I confirm Whacky Auctions is covered by a current second-hand-goods dealer registration for its trading activities/premises.</label><button class="btn btn-secondary">Save registration status</button></form><div style="margin-top:16px"><div class="label">Soft close default</div><b>${Number(d.settings.soft_close_seconds||120)} seconds</b></div>${ready?`<button class="btn btn-${d.settings.trading_enabled?'danger':'primary'}" id="tradeToggle" style="margin-top:14px">${d.settings.trading_enabled?'Disable trading':'Enable trading'}</button>`:'<p class="muted small">The trading switch stays unavailable until the SAPS registration is recorded and the payment gateway is connected.</p>'}</div>`}
async function adminAuctions(){
  const d=await api('admin/auctions');
  const edit=state.editingAuction||{};
  const val=(k,def='')=>edit[k]??def;
  const condition=quickConditionParts(val('condition',''));
  const softDefault=Number(val('softCloseSeconds',state.settings.softCloseSeconds||120));
  const defaultStart=toLocalInput(val('startAt',new Date(now()+25*60*60*1000).toISOString()));
  const closeValue=toLocalInput(val('scheduledEndAt'));
  ensureQuickPhotos(edit);
  const formOrConfirmation=state.quickSavedAuction?quickConfirmation(state.quickSavedAuction):`<div class="panel quick-list-panel" id="quickListPanel">
    <div class="section-head quick-list-head"><div><div class="label">Fast mobile listing</div><h3>${edit.id?'Edit draft':'Quick List'}</h3><p class="muted small">Photos → title → condition → price → closing time → save. Standard auction defaults stay in Advanced settings.</p></div>${edit.id?'<button class="btn btn-secondary" id="cancelEdit">New listing</button>':''}</div>
    <form id="auctionForm" class="admin-form quick-list-form" novalidate>
      <input type="hidden" name="id" value="${esc(edit.id||'')}">
      <section class="quick-photo-section" id="quickPhotos">
        <div class="quick-field-head"><div><label>Photos</label><div class="muted small">First photo is the cover. Add now or save the draft and add later.</div></div><span class="photo-count" id="quickPhotoCount"></span></div>
        <div class="quick-photo-actions">
          <label class="btn btn-primary quick-photo-button">📷 Take photo<input id="quickCameraInput" type="file" accept="image/*" capture="environment" hidden></label>
          <label class="btn btn-secondary quick-photo-button">🖼️ Choose photos<input id="quickGalleryInput" type="file" accept="image/*" multiple hidden></label>
        </div>
        <div class="quick-photo-grid" id="quickPhotoTray" aria-live="polite"></div>
        <div class="muted small">JPEG, PNG, WebP or GIF · up to 8 MB each. Use arrows to change order.</div>
      </section>
      <div id="quickListError" class="notice bad quick-error" hidden></div>
      <div class="field"><label>Item title</label><input class="input quick-input" name="title" maxlength="150" required autocomplete="off" value="${esc(val('title'))}" placeholder="e.g. Defy Slimline Hob"></div>
      <div class="field"><label>Condition</label><select class="select quick-input" name="conditionChoice" required>${QUICK_CONDITIONS.map(x=>`<option value="${esc(x)}" ${condition.choice===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
      <div class="field"><label>Short condition note <span class="muted">(optional)</span></label><input class="input quick-input" name="conditionNote" maxlength="500" value="${esc(condition.note)}" placeholder="e.g. Light scratches; powers on"></div>
      <div class="field"><label>Description <span class="muted">(optional)</span></label><textarea class="textarea quick-description" name="description" maxlength="12000" placeholder="Anything useful the bidder should know">${esc(val('description'))}</textarea></div>
      <div class="form-grid quick-money-grid"><div class="field"><label>Opening bid (R)</label><input class="input quick-input" type="number" inputmode="decimal" step="0.01" min="0" name="openingBid" required value="${val('openingBidCents')!=null?Number(val('openingBidCents'))/100:'1.00'}"></div><div class="field"><label>Reserve price (R) <span class="muted">optional</span></label><input class="input quick-input" type="number" inputmode="decimal" step="0.01" min="0" name="reserve" value="${edit.reservePriceCents!=null?Number(edit.reservePriceCents)/100:''}" placeholder="No reserve"></div></div>
      <div class="field"><label>Auction closing date/time</label><input class="input quick-input" type="datetime-local" name="endAt" required value="${closeValue}"></div>
      <details class="advanced-settings"><summary>Advanced settings <span>Optional / unusual lots</span></summary><div class="advanced-body">
        <div class="form-grid"><div class="field"><label>Category</label><input class="input" name="category" value="${esc(val('category','General'))}"></div><div class="field"><label>Start date/time</label><input class="input" type="datetime-local" name="startAt" required value="${defaultStart}"></div></div>
        <div class="form-grid"><div class="field"><label>Bid increment (R)</label><input class="input" type="number" inputmode="decimal" step="0.01" min="0.01" name="increment" required value="${val('bidIncrementCents')!=null?Number(val('bidIncrementCents'))/100:'10.00'}"></div><div class="field"><label>Buyer premium %</label><input class="input" type="number" inputmode="decimal" step="0.01" min="0" name="premium" value="${esc(val('buyerPremiumPercent',0))}"></div></div>
        <div class="form-grid"><div class="field"><label>Soft close seconds</label><input class="input" type="number" inputmode="numeric" min="30" max="900" name="softClose" value="${esc(softDefault)}"></div><div class="field"><label>Payment deadline hours</label><input class="input" type="number" inputmode="numeric" min="1" name="paymentHours" value="${esc(val('paymentDeadlineHours',24))}"></div></div>
        <div class="field"><label>Appointed auctioneer</label><input class="input" name="auctioneerName" value="${esc(val('auctioneerName'))}" placeholder="Required before publication"></div>
        <div class="field"><label>VAT note</label><input class="input" name="vatNote" value="${esc(val('vatNote','VAT treatment as displayed for this lot.'))}"></div>
        <div class="field"><label>Inspection note</label><input class="input" name="inspectionNote" value="${esc(val('inspectionNote','Inspection by arrangement before bidding closes.'))}"></div>
        <div class="field"><label>Collection / delivery note</label><input class="input" name="collectionNote" value="${esc(val('collectionNote','Collection arrangements will be shown to the winning bidder.'))}"></div>
        <div class="field"><label>Storage fee note</label><input class="input" name="storageFeeNote" value="${esc(val('storageFeeNote','Storage charges may apply after the collection deadline where lawfully disclosed.'))}"></div>
        <label class="switch"><input type="checkbox" name="reserveDisclosed" ${edit.reserveDisclosed===false?'':'checked'}> Reserve status disclosed to bidders</label>
        <div class="notice"><b>Standard rules remain active.</b><br>Quick List does not change the rolling soft close, payment period, auction rules, server-time handling or launch controls.</div>
      </div></details>
      <div class="sticky-save"><button class="btn btn-primary quick-save" id="saveDraftBtn" type="submit">${edit.id?'Save Draft Changes':'Save Draft'}</button></div>
    </form>
  </div>`;
  const inventory=d.auctions.length?`<div class="inventory-list">${d.auctions.map(a=>`<article class="inventory-item" id="lot-${a.id}"><div class="inventory-thumb">${a.images[0]?`<img src="${esc(a.images[0].url)}" alt="${esc(a.title)}">`:'<span>No photo</span>'}</div><div class="inventory-main"><div class="inventory-title-row"><div><b>${esc(a.title)}</b><div class="muted small">${esc(a.category)} · ${a.images.length} photo${a.images.length===1?'':'s'}</div></div>${statusChip(a)}</div><div class="inventory-meta"><span>Close ${fmtDate(a.currentEndAt)}</span><span>${randMoney(a.currentBidCents??a.openingBidCents)}</span></div><div class="toolbar inventory-actions"><button class="btn btn-secondary" data-edit-auction="${a.id}">Edit</button><button class="btn btn-secondary" data-images-auction="${a.id}">Photos</button><button class="btn btn-secondary" data-preview-auction="${a.id}">Preview</button>${a.status==='draft'?`<button class="btn btn-secondary" data-duplicate-auction="${a.id}">Duplicate</button><button class="btn btn-secondary" data-test-yoco="${a.id}">Test Yoco</button><button class="btn btn-accent" data-publish-auction="${a.id}">Publish</button>`:''}</div></div></article>`).join('')}</div>`:'<div class="empty">No auctions yet.</div>';
  return `${formOrConfirmation}<div class="panel inventory-panel" id="inventory" style="margin-top:16px"><div class="section-head"><div><div class="label">Stock</div><h3>Auction inventory</h3></div>${state.quickSavedAuction?'<button class="btn btn-primary" id="newQuickListing">+ Quick List</button>':''}</div>${inventory}</div>`;
}
function toLocalInput(v){if(!v)return'';const d=new Date(v);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
const QUICK_CONDITIONS=['New','Like New','Good','Fair','Poor','Untested','For parts','Other'];
function quickConditionParts(text=''){
  const raw=String(text||'').trim();
  for(const choice of QUICK_CONDITIONS.filter(x=>x!=='Other')){
    if(raw===choice)return{choice,note:''};
    if(raw.startsWith(choice+' — '))return{choice,note:raw.slice(choice.length+3)};
  }
  return raw?{choice:'Other',note:raw}:{choice:'Good',note:''};
}
function quickConditionText(choice,note){
  const c=QUICK_CONDITIONS.includes(String(choice))?String(choice):'Good';
  const n=String(note||'').trim();
  if(c==='Other')return n||'Other';
  return n?`${c} — ${n}`:c;
}
function cleanupQuickObjectUrls(){for(const p of state.quickPhotos||[])if(p.kind==='new'&&p.url)URL.revokeObjectURL(p.url)}
function ensureQuickPhotos(edit={}){
  const key=edit?.id||'new';
  if(state.quickPhotoKey===key)return;
  cleanupQuickObjectUrls();
  state.quickPhotoKey=key;
  state.quickPhotos=(edit?.images||[]).map(im=>({kind:'existing',id:im.id,url:im.url,alt:im.alt||edit.title||''}));
  state.quickOriginalImageIds=state.quickPhotos.map(x=>x.id);
}
function resetQuickPhotos(edit={}){state.quickPhotoKey=null;ensureQuickPhotos(edit)}
function renderQuickPhotoTray(){
  const tray=$('#quickPhotoTray'),count=$('#quickPhotoCount');if(!tray)return;
  if(count)count.textContent=`${state.quickPhotos.length} photo${state.quickPhotos.length===1?'':'s'}`;
  if(!state.quickPhotos.length){tray.innerHTML='<div class="quick-photo-empty">No photos selected yet.</div>';return}
  tray.innerHTML=state.quickPhotos.map((p,i)=>`<div class="quick-photo-card"><div class="quick-photo-img"><img src="${esc(p.url)}" alt="${esc(p.alt||`Photo ${i+1}`)}">${i===0?'<span class="cover-badge">Cover</span>':''}</div><div class="quick-photo-controls"><button type="button" class="photo-move" data-photo-left="${i}" aria-label="Move photo left" ${i===0?'disabled':''}>←</button><button type="button" class="photo-move" data-photo-right="${i}" aria-label="Move photo right" ${i===state.quickPhotos.length-1?'disabled':''}>→</button><button type="button" class="photo-remove" data-photo-remove="${i}" aria-label="Remove photo">×</button></div></div>`).join('');
}
function addQuickFiles(fileList){
  const allowed=new Set(['image/jpeg','image/png','image/webp','image/gif']);let added=0;
  for(const file of [...(fileList||[])]){
    if(!allowed.has(file.type)){toast(`${file.name}: use JPEG, PNG, WebP or GIF.`,true);continue}
    if(file.size>8*1024*1024){toast(`${file.name}: image must be 8 MB or smaller.`,true);continue}
    state.quickPhotos.push({kind:'new',file,url:URL.createObjectURL(file),alt:''});added++;
  }
  if(added)renderQuickPhotoTray();
}
function bindQuickPhotoControls(){
  const camera=$('#quickCameraInput'),gallery=$('#quickGalleryInput'),tray=$('#quickPhotoTray');
  if(camera)camera.onchange=e=>{addQuickFiles(e.target.files);camera.value=''};
  if(gallery)gallery.onchange=e=>{addQuickFiles(e.target.files);gallery.value=''};
  if(tray){tray.onclick=e=>{const remove=e.target.closest('[data-photo-remove]'),left=e.target.closest('[data-photo-left]'),right=e.target.closest('[data-photo-right]');let i;
    if(remove){i=Number(remove.dataset.photoRemove);const [item]=state.quickPhotos.splice(i,1);if(item?.kind==='new'&&item.url)URL.revokeObjectURL(item.url);renderQuickPhotoTray();return}
    if(left){i=Number(left.dataset.photoLeft);if(i>0)[state.quickPhotos[i-1],state.quickPhotos[i]]=[state.quickPhotos[i],state.quickPhotos[i-1]];renderQuickPhotoTray();return}
    if(right){i=Number(right.dataset.photoRight);if(i<state.quickPhotos.length-1)[state.quickPhotos[i],state.quickPhotos[i+1]]=[state.quickPhotos[i+1],state.quickPhotos[i]];renderQuickPhotoTray()}
  }}
  renderQuickPhotoTray();
}
async function saveQuickPhotos(aid,title){
  for(const item of state.quickPhotos){
    if(item.kind!=='new')continue;
    const form=new FormData();form.append('file',item.file);form.append('alt',title||'Auction item');
    const d=await api(`admin/auctions/${aid}/image`,{method:'POST',body:form});
    if(item.url)URL.revokeObjectURL(item.url);
    item.kind='existing';item.id=d.image.id;item.url=d.image.url;item.alt=title||'';delete item.file;
  }
  const desiredIds=state.quickPhotos.filter(x=>x.kind==='existing').map(x=>x.id);
  const desiredSet=new Set(desiredIds);
  for(const oldId of state.quickOriginalImageIds)if(!desiredSet.has(oldId)){try{await api(`admin/images/${oldId}`,{method:'DELETE'})}catch(e){if(e.status!==404)throw e}}
  await api(`admin/auctions/${aid}/images/reorder`,{method:'POST',body:{imageIds:desiredIds}});
  state.quickOriginalImageIds=[...desiredIds];
}
function setQuickError(message=''){
  const box=$('#quickListError');if(!box)return;
  box.hidden=!message;box.textContent=message;
  if(message)box.scrollIntoView({behavior:'smooth',block:'center'});
}
function quickConfirmation(a){return `<div class="panel quick-confirm"><div class="quick-confirm-icon">✓</div><div class="label">Draft saved</div><h3>${esc(a.title)}</h3><p class="muted">${a.images?.length||0} photo${a.images?.length===1?'':'s'} · closes ${fmtDate(a.scheduledEndAt)}</p><div class="quick-confirm-actions"><button class="btn btn-primary" data-confirm-edit="${a.id}">Edit</button><button class="btn btn-secondary" data-confirm-photos="${a.id}">Add / reorder photos</button><button class="btn btn-secondary" data-preview-auction="${a.id}">Preview listing</button><button class="btn btn-secondary" data-duplicate-auction="${a.id}">Duplicate listing</button><button class="btn btn-secondary" data-back-inventory>Back to inventory</button></div></div>`}
async function openQuickEdit(aid,focusPhotos=false){
  const d=await api('auctions/'+aid);state.editingAuction=d.auction;state.quickSavedAuction=null;resetQuickPhotos(d.auction);await render();
  setTimeout(()=>$(focusPhotos?'#quickPhotos':'#quickListPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),50);
}
async function duplicateAuction(aid){
  try{const d=await api(`admin/auctions/${aid}/duplicate`,{method:'POST'});const auction=d.auction||(await api('auctions/'+d.auctionId)).auction;state.editingAuction=auction;state.quickSavedAuction=null;resetQuickPhotos(auction);toast('Draft duplicated. Change the title, photos or price and save.');await render();setTimeout(()=>$('#quickListPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),50)}catch(e){toast(e.message,true)}
}
async function adminUsers(){const d=await api('admin/users');return `<div class="panel"><h3>Bidder verification</h3><p class="muted small">Review the bidder's identity/contact information before activating bidding privileges.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>ID / DOB</th><th>Address</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.users.filter(u=>u.role==='bidder').map(u=>`<tr><td><b>${esc(u.first_name)} ${esc(u.last_name)}</b></td><td>${esc(u.email)}<br>${esc(u.mobile)}</td><td>${esc(u.id_number)}<br>${esc(String(u.date_of_birth).slice(0,10))}</td><td>${esc(u.physical_address)}</td><td>${u.suspended?'Suspended':u.verified?'Verified':'Pending'}</td><td><div class="toolbar"><button class="btn btn-secondary small" data-verify-user="${u.id}" data-value="${u.verified?'0':'1'}">${u.verified?'Unverify':'Verify'}</button><button class="btn btn-danger small" data-suspend-user="${u.id}" data-value="${u.suspended?'0':'1'}">${u.suspended?'Unsuspend':'Suspend'}</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function adminRecords(){return `<div class="panel"><h3>Statutory auction records</h3><p>Export the bidder record and vendor roll for retention and compliance administration.</p><div class="toolbar"><a class="btn btn-secondary" href="/api/admin/records/bidders.csv">Download bidders CSV</a><a class="btn btn-secondary" href="/api/admin/records/vendor-roll.csv">Download vendor roll CSV</a></div><p class="muted small">Keep auction records for the period required by applicable law. Access to these exports is restricted to administrator sessions.</p></div>`}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div></div><button class="x" id="modalX">×</button></div>${html}</div></div>`);$('#modalX').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()})}
function closeModal(){$('#modal')?.remove()}
function showLogin(register=false){modal(`<h2>${register?'Create bidder account':'Sign in'}</h2><div class="tabs"><button class="tab ${!register?'active':''}" id="loginTab">Sign in</button><button class="tab ${register?'active':''}" id="registerTab">Register</button></div><div id="authBody">${register?registerForm():loginForm()}</div>`);$('#loginTab').onclick=()=>{$('#authBody').innerHTML=loginForm();bindAuth()};$('#registerTab').onclick=()=>{$('#authBody').innerHTML=registerForm();bindAuth()};bindAuth()}
function loginForm(){return `<form id="loginForm" class="admin-form"><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Password</label><input class="input" name="password" type="password" required></div><button class="btn btn-primary">Sign in</button></form>`}
function registerForm(){return `<form id="registerForm" class="admin-form"><div class="form-grid"><div class="field"><label>First name</label><input class="input" name="firstName" required></div><div class="field"><label>Last name</label><input class="input" name="lastName" required></div></div><div class="form-grid"><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Mobile</label><input class="input" name="mobile" required></div></div><div class="form-grid"><div class="field"><label>ID / passport number</label><input class="input" name="idNumber" required></div><div class="field"><label>Date of birth</label><input class="input" type="date" name="dateOfBirth" required></div></div><div class="field"><label>Physical address</label><textarea class="textarea" name="physicalAddress" required></textarea></div><div class="field"><label>Password</label><input class="input" type="password" minlength="10" name="password" required></div><label class="switch"><input type="checkbox" name="acceptTerms" required> I accept the <a href="/legal/terms-auction-rules.pdf" target="_blank">Terms & Auction Rules</a>.</label><label class="switch"><input type="checkbox" name="acceptPrivacy" required> I have read the <a href="/legal/privacy-policy.pdf" target="_blank">POPIA Privacy Notice</a>.</label><label class="switch"><input type="checkbox" name="marketingOptIn"> I want to receive Whacky Auctions marketing (optional).</label><button class="btn btn-primary">Create account</button><p class="muted small">Bidder registration details are retained for auction compliance and verification.</p></form>`}
function bindAuth(){const lf=$('#loginForm');if(lf)lf.onsubmit=async e=>{e.preventDefault();const f=new FormData(lf);try{const d=await api('login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});state.me=d.me;closeModal();toast('Signed in.');render()}catch(x){toast(x.message,true)}};const rf=$('#registerForm');if(rf)rf.onsubmit=async e=>{e.preventDefault();const f=new FormData(rf);try{const d=await api('register',{method:'POST',body:{firstName:f.get('firstName'),lastName:f.get('lastName'),email:f.get('email'),mobile:f.get('mobile'),idNumber:f.get('idNumber'),dateOfBirth:f.get('dateOfBirth'),physicalAddress:f.get('physicalAddress'),password:f.get('password'),acceptTerms:f.get('acceptTerms')==='on',acceptPrivacy:f.get('acceptPrivacy')==='on',marketingOptIn:f.get('marketingOptIn')==='on'}});state.me=d.me;closeModal();toast(d.message);render()}catch(x){toast(x.message,true)}}}
async function imageModal(aid){openQuickEdit(aid,true)}
function installUI(){if(state.deferredInstall&&!$('#installBanner'))document.body.insertAdjacentHTML('beforeend',`<div class="install-banner" id="installBanner"><p><b>Install Whacky Auctions</b><br>Add the app to your phone for a full-screen experience.</p><button class="btn btn-primary" id="installBtn">Install</button></div>`),$('#installBtn').onclick=async()=>{state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;$('#installBanner')?.remove()}}
async function bind(){const lb=$('#loginBtn'),hb=$('#heroRegister'),lh=$('#loginHere'),ab=$('#accountBtn');if(lb)lb.onclick=()=>showLogin(false);if(hb)hb.onclick=()=>showLogin(true);if(lh)lh.onclick=()=>showLogin(false);if(ab)ab.onclick=()=>go('/profile');const mb=$('#mobileBtn');if(mb)mb.onclick=()=>modal(`<h2>Menu</h2><div class="legal-list"><a class="legal-link" data-link href="/">Auctions</a>${state.me?'<a class="legal-link" data-link href="/my-bids">My bids</a><a class="legal-link" data-link href="/watchlist">Watchlist</a><a class="legal-link" data-link href="/wins">Wins</a><a class="legal-link" data-link href="/profile">Account</a>':''}${state.me?.role==='admin'?'<a class="legal-link" data-link href="/admin">Admin</a>':''}<a class="legal-link" data-link href="/legal">Legal</a></div>`);$$('#modal [data-link]').forEach(x=>x.addEventListener('click',closeModal));$$('[data-photo]').forEach((b,i)=>b.onclick=()=>{$('#mainPhoto').src=b.dataset.photo;$$('[data-photo]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});const watch=$('#watchBtn');if(watch)watch.onclick=async()=>{if(!state.me)return showLogin();const id=route().split('/')[1];try{const d=await api('watchlist/'+id,{method:'POST'});watch.textContent=d.watched?'★ Watching':'☆ Watch';toast(d.watched?'Added to watchlist':'Removed from watchlist')}catch(e){toast(e.message,true)}};$$('[data-retract-bid]').forEach(b=>b.onclick=async()=>{const reason=prompt('Reason for bid retraction (before sale completion):','Bid entered in error')||'Bidder retraction before completion';if(!confirm('Retract this bid? This action is recorded in the auction log.'))return;try{await api(`bids/${b.dataset.retractBid}/retract`,{method:'POST',body:{reason}});toast('Bid retracted.');render()}catch(e){toast(e.message,true)}});const payNow=$('#payNow');if(payNow)payNow.onclick=async()=>{const id=route().split('/')[1];payNow.disabled=true;try{const d=await api(`checkout/${id}`,{method:'POST'});if(d.redirectUrl)location.href=d.redirectUrl;else toast(d.message||'Payment started.')}catch(e){toast(e.message,true)}finally{payNow.disabled=false}};const pb=$('#placeBid');if(pb)pb.onclick=async()=>{const id=route().split('/')[1],amount=Math.round(Number($('#bidAmount').value)*100);if(!confirm(`Place a binding bid of ${randMoney(amount)}?`))return;pb.disabled=true;try{const d=await api(`auctions/${id}/bid`,{method:'POST',body:{amountCents:amount}});toast(d.softCloseExtended?'Bid placed — soft close extended.':'Bid placed.');await render()}catch(e){toast(e.message,true)}finally{pb.disabled=false}};$$('[data-tab]').forEach(t=>t.onclick=async()=>{const id=route().split('/')[1],d=await api('auctions/'+id);$$('[data-tab]').forEach(x=>x.classList.remove('active'));t.classList.add('active');$('#tabBody').innerHTML=detailTab(d.auction,t.dataset.tab)});const lo=$('#logoutBtn');if(lo)lo.onclick=async()=>{await api('logout',{method:'POST'});state.me=null;go('/')};const pf=$('#passwordForm');if(pf)pf.onsubmit=async e=>{e.preventDefault();const f=new FormData(pf);try{await api('me/password',{method:'POST',body:{currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')}});toast('Password changed.');pf.reset()}catch(x){toast(x.message,true)}};const rn=$('#readNotes');if(rn)rn.onclick=async()=>{await api('me/notifications/read',{method:'POST'});toast('Notifications marked read.');render()};$$('[data-admin-tab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminTab;state.editingAuction=null;render()});const ipb=$('#installPageBtn');if(ipb&&state.deferredInstall)ipb.onclick=async()=>{state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;render()};const pr=$('#printRules');if(pr)pr.onclick=()=>print();const drf=$('#dealerRegistrationForm');if(drf)drf.onsubmit=async e=>{e.preventDefault();const f=new FormData(drf);try{await api('admin/settings/dealer-registration',{method:'POST',body:{registrationNumber:f.get('registrationNumber'),expiryDate:f.get('expiryDate'),confirmed:f.get('confirmed')==='on'}});toast('Registration status saved.');await bootstrap()}catch(x){toast(x.message,true)}};const tt=$('#tradeToggle');if(tt)tt.onclick=async()=>{const desired=tt.textContent.includes('Enable');if(desired&&!confirm('Only enable trading once Whacky Auctions is legally ready to trade and the payment gateway is active. Continue?'))return;try{await api('admin/settings/trading',{method:'POST',body:{enabled:desired}});state.settings.tradingEnabled=desired;toast(desired?'Trading enabled.':'Trading disabled.');render()}catch(e){toast(e.message,true)}};const sf=$('#adminSetupForm');if(sf)sf.onsubmit=async e=>{e.preventDefault();const f=new FormData(sf);try{const d=await api('admin/setup',{method:'POST',body:{code:f.get('code'),password:f.get('password')}});state.me=d.me;toast(d.message);go('/admin')}catch(x){toast(x.message,true)}};const af=$('#auctionForm');if(af)af.onsubmit=saveAuction;bindQuickPhotoControls();const ce=$('#cancelEdit');if(ce)ce.onclick=()=>{state.editingAuction=null;state.quickSavedAuction=null;resetQuickPhotos({});render()};const nq=$('#newQuickListing');if(nq)nq.onclick=()=>{state.editingAuction=null;state.quickSavedAuction=null;resetQuickPhotos({});render()};$$('[data-edit-auction]').forEach(b=>b.onclick=()=>openQuickEdit(b.dataset.editAuction));$$('[data-images-auction]').forEach(b=>b.onclick=()=>imageModal(b.dataset.imagesAuction));$$('[data-confirm-edit]').forEach(b=>b.onclick=()=>openQuickEdit(b.dataset.confirmEdit));$$('[data-confirm-photos]').forEach(b=>b.onclick=()=>openQuickEdit(b.dataset.confirmPhotos,true));$$('[data-preview-auction]').forEach(b=>b.onclick=()=>go('/auction/'+b.dataset.previewAuction));$$('[data-duplicate-auction]').forEach(b=>b.onclick=()=>duplicateAuction(b.dataset.duplicateAuction));$$('[data-back-inventory]').forEach(b=>b.onclick=()=>{state.quickSavedAuction=null;state.editingAuction=null;resetQuickPhotos({});render();setTimeout(()=>$('#inventory')?.scrollIntoView({behavior:'smooth',block:'start'}),50)});$('[data-test-yoco]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=await api(`admin/auctions/${b.dataset.testYoco}/test-checkout`,{method:'POST'});toast(`Opening Yoco test checkout for ${randMoney(d.amountCents)}.`);location.href=d.redirectUrl}catch(e){toast(e.message,true);b.disabled=false}});$('[data-publish-auction]').forEach(b=>b.onclick=async()=>{if(!confirm('Publish this auction? The auction-specific rules must remain available as required by law.'))return;try{await api(`admin/auctions/${b.dataset.publishAuction}/publish`,{method:'POST'});toast('Auction published.');render()}catch(e){toast(e.message,true)}});$$('[data-verify-user]').forEach(b=>b.onclick=async()=>{await api(`admin/users/${b.dataset.verifyUser}/verify`,{method:'POST',body:{verified:b.dataset.value==='1'}});toast('Bidder status updated.');render()});$$('[data-suspend-user]').forEach(b=>b.onclick=async()=>{await api(`admin/users/${b.dataset.suspendUser}/suspend`,{method:'POST',body:{suspended:b.dataset.value==='1'}});toast('Account status updated.');render()});installUI()}
async function saveAuction(e){
  e.preventDefault();setQuickError('');
  const form=e.target,f=new FormData(form),saveBtn=$('#saveDraftBtn');
  const title=String(f.get('title')||'').trim();
  const endRaw=String(f.get('endAt')||'');
  const startRaw=String(f.get('startAt')||'');
  const opening=Number(f.get('openingBid'));
  if(!title)return setQuickError('Enter an item title.');
  if(!f.get('conditionChoice'))return setQuickError('Choose the item condition.');
  if(!Number.isFinite(opening)||opening<0)return setQuickError('Enter a valid opening bid.');
  if(!endRaw)return setQuickError('Choose the auction closing date and time.');
  const start=new Date(startRaw),end=new Date(endRaw);
  if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return setQuickError('Check the auction start and closing date/time.');
  if(!(start<end))return setQuickError('The closing time must be after the start time. Open Advanced settings to adjust the start time.');
  const reserveRaw=String(f.get('reserve')??'');
  const reserve=reserveRaw===''?null:Number(reserveRaw);
  if(reserve!=null&&(!Number.isFinite(reserve)||reserve<0))return setQuickError('Enter a valid reserve price or leave it blank.');
  const payload={
    title,category:f.get('category')||'General',description:String(f.get('description')||'').trim(),conditionText:quickConditionText(f.get('conditionChoice'),f.get('conditionNote')),
    startAt:start.toISOString(),endAt:end.toISOString(),openingBidCents:Math.round(opening*100),bidIncrementCents:Math.round(Number(f.get('increment')||10)*100),
    reservePriceCents:reserve==null?null:Math.round(reserve*100),buyerPremiumPercent:Number(f.get('premium')||0),softCloseSeconds:Number(f.get('softClose')||state.settings.softCloseSeconds||120),
    paymentDeadlineHours:Number(f.get('paymentHours')||24),auctioneerName:f.get('auctioneerName'),vatNote:f.get('vatNote'),inspectionNote:f.get('inspectionNote'),collectionNote:f.get('collectionNote'),storageFeeNote:f.get('storageFeeNote'),reserveDisclosed:f.get('reserveDisclosed')==='on'
  };
  let aid=String(f.get('id')||'');
  if(saveBtn)saveBtn.disabled=true;
  try{
    if(aid)await api('admin/auctions/'+aid,{method:'PUT',body:payload});
    else{const d=await api('admin/auctions',{method:'POST',body:payload});aid=d.auctionId;const hidden=form.querySelector('[name=id]');if(hidden)hidden.value=aid}
    await saveQuickPhotos(aid,title);
    const latest=await api('auctions/'+aid);state.quickSavedAuction=latest.auction;state.editingAuction=null;state.quickPhotoKey=null;state.quickPhotos=[];state.quickOriginalImageIds=[];toast('Draft saved.');await render();setTimeout(()=>$('.quick-confirm')?.scrollIntoView({behavior:'smooth',block:'start'}),50);
  }catch(x){setQuickError(x.message);toast(x.message,true)}finally{if(saveBtn)saveBtn.disabled=false}
}
async function render(){const app=$('#app');const r=route();app.innerHTML='<div class="container" style="padding:80px 0"><div class="muted">Loading Whacky Auctions…</div></div>';let html;try{if(r==='home')html=await home();else if(r.startsWith('auction/'))html=await auctionPage(r.split('/')[1]);else if(r==='my-bids')html=await accountList('bids');else if(r==='watchlist')html=await accountList('watchlist');else if(r==='wins')html=await accountList('wins');else if(r==='profile')html=await profile();else if(r==='legal')html=legal();else if(r==='install')html=installPage();else if(r.startsWith('rules/'))html=await rulesPage(r.split('/')[1]);else if(r==='admin-setup')html=adminSetup();else if(r==='admin')html=await admin();else html=errorPage('Page not found.')}catch(e){console.error(e);html=errorPage(e.message||'Something went wrong.')}app.innerHTML=html;await bind();tick()}
function tick(){$$('[data-countdown]').forEach(el=>{el.textContent=countdown(el.dataset.countdown,el.dataset.status)})}
setInterval(tick,1000);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredInstall=e;installUI()});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(console.error));
bootstrap();
